<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { genId } from '../utils/id'
import { useRoute } from 'vue-router'
import { customerServiceApi, customerServiceMessageApi } from '../api/customer-rag'
import { tradingApi } from '../api/trading'
import AgentTracePanel from './AgentTracePanel.vue'
import { profileApi } from '../api/profile'
import AnalysisResultCard from './AnalysisResultCard.vue'

const route=useRoute(),open=ref(false),query=ref(''),loading=ref(false),error=ref(''),messages=ref<any[]>([]),conversationId=ref(sessionStorage.getItem('customer_service_conversation_id')||genId()),humanSessionId=ref(sessionStorage.getItem('customer_service_session_id')||''),poller=ref<number|undefined>(undefined),unread=ref(0),drafting=ref(false),confirmingDraftId=ref(''),acknowledgedDrafts=ref<Record<string,boolean>>({}),recommending=ref(false)
sessionStorage.setItem('customer_service_conversation_id', conversationId.value)
const visible=computed(()=>route.path!=='/login'&&route.path!=='/register')
function startPolling(){if(poller.value||!humanSessionId.value)return;poller.value=window.setInterval(async()=>{if(!humanSessionId.value)return;try{const data=(await customerServiceMessageApi.messages(humanSessionId.value)).data.data||[];const next=data.map((x:any)=>({role:x.sender_type==='customer'?'user':'assistant',text:x.content,...x}));if(!open.value&&next.length>messages.value.filter((x:any)=>x.id).length)unread.value+=next.length-messages.value.filter((x:any)=>x.id).length;messages.value=[...messages.value.filter((x:any)=>x.role==='user'&&!x.id),...next]}catch{}} ,2500)}
function stopPolling(){if(poller.value)window.clearInterval(poller.value);poller.value=undefined}
async function validateHumanSession(){if(!humanSessionId.value)return;try{const session=(await customerServiceMessageApi.session(humanSessionId.value)).data.data;if(!['waiting_human','human_active','paused'].includes(session.status)){humanSessionId.value='';sessionStorage.removeItem('customer_service_session_id');stopPolling()}}catch{humanSessionId.value='';sessionStorage.removeItem('customer_service_session_id');stopPolling()}}
function toggle(){open.value=!open.value;if(open.value)unread.value=0}
function isPurchaseIntent(text:string){return /(申购|购买|买入|下单)/.test(text) && !/(推荐|适合|买什么|产品建议|订单状态|查询订单|订单号)/.test(text)}
function isRecommendationIntent(text:string){return /(推荐|适合我|适合我的|买什么|产品建议)/.test(text) && !isPurchaseIntent(text)}
function responseError(e:any){return e?.response?.data?.detail?.message||e?.response?.data?.detail||e?.message||'助手服务暂时不可用'}
function money(value:any){return Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function mergeRecommendation(message:any, data:any){
  const operationResult=data.results?.find((item:any)=>item.intent==='business_operation'&&item.data?.recommended_purchase)
  const recommendationResult=data.results?.find((item:any)=>item.intent==='product_recommendation'&&item.data?.recommendation)
  return {
    ...message,
    recommendation: recommendationResult?.data?.recommendation||operationResult?.data?.recommendation,
    recommended_purchase: operationResult ? { amount_text: operationResult.data.explicit_amount_text } : undefined,
  }
}
function displayRecommendation(message:any){
  if(message.recommendation)return message.recommendation
  const nested=message.results?.find((item:any)=>item.intent==='product_recommendation'&&item.data?.recommendation)
  return nested?.data?.recommendation||null
}
function recommendationForMessage(message:any){
  return displayRecommendation(message) || message.results?.find((item:any)=>item.intent==='business_operation'&&item.data?.recommended_purchase)?.data?.recommendation || null
}
async function send(){const text=query.value.trim();if(!text||loading.value)return;query.value='';loading.value=true;error.value='';try{if(humanSessionId.value){const message=(await customerServiceMessageApi.send(humanSessionId.value,text)).data.data;messages.value.push({role:'user',text:message.content,id:message.id});return}messages.value.push({role:'user',text});if(isPurchaseIntent(text) && !isRecommendationIntent(text)){drafting.value=true;const draft=(await tradingApi.createNaturalLanguageDraft(text)).data.data;messages.value.push({role:'assistant',answer:draft.clarification||'已生成交易草稿。',trade_draft:draft});return}const data=(await customerServiceApi.execute(text,conversationId.value,route.path)).data.data;const recommendationResult=data.results?.find((item:any)=>item.intent==='product_recommendation'&&item.data?.recommendation);const operationResult=data.results?.find((item:any)=>item.intent==='business_operation'&&item.data?.recommended_purchase);const analysisResults=(data.results||[]).filter((item:any)=>item.intent==='data_analysis'&&item.data);const baseMessage={role:'assistant',analysis_results:analysisResults,...data};if(operationResult){messages.value.push(mergeRecommendation({...baseMessage,answer:operationResult.answer},data));}else if(recommendationResult){messages.value.push(mergeRecommendation({...baseMessage,answer:recommendationResult.answer},data));}else{messages.value.push(baseMessage);}if(data.customer_service_session_id){humanSessionId.value=data.customer_service_session_id;sessionStorage.setItem('customer_service_session_id',humanSessionId.value);startPolling()}}catch(e:any){error.value=responseError(e)}finally{loading.value=false;drafting.value=false;recommending.value=false}}
async function confirmTradeDraft(message:any){const draft=message.trade_draft;if(!draft?.draft_id||!draft?.confirmation_token||confirmingDraftId.value)return;confirmingDraftId.value=draft.draft_id;error.value='';try{const order=(await tradingApi.confirmNaturalLanguageDraft(draft.draft_id,{confirmation_token:draft.confirmation_token,idempotency_key:`bubble-nl-confirm-${draft.draft_id}-v${draft.version}`})).data.data;draft.status='confirmed_order_created';draft.order=order;messages.value.push({role:'assistant',answer:`订单 ${order.order_no||order.id} 已创建，当前为待确认状态。请在“我的订单”中完成后续确认。`})}catch(e:any){error.value=responseError(e)}finally{confirmingDraftId.value=''}}
function closeHuman(){if(!humanSessionId.value)return;customerServiceMessageApi.customerClose(humanSessionId.value).then(()=>{humanSessionId.value='';sessionStorage.removeItem('customer_service_session_id');stopPolling()})}
onMounted(async()=>{await validateHumanSession();if(humanSessionId.value)startPolling()})
</script>
<template><div v-if="visible" class="agent-bubble-widget" data-testid="agent-bubble-widget"><Transition name="service-pop"><section v-if="open" class="agent-bubble-panel" data-testid="agent-bubble-panel"><header><div><span>智能助手</span><small>统一 Agent 入口 · 客服、推荐与受控交易在同一窗口完成</small></div><button @click="open=false">×</button></header><div class="service-messages" data-testid="agent-bubble-messages"><p v-if="!messages.length" class="service-welcome">您好，我是统一智能助手。您可以咨询客服问题、产品与风险，也可直接说“我要申购某产品 10 万元”。</p><article v-for="(message,index) in messages" :key="index" :class="'service-message '+message.role"><p v-if="message.text||message.answer||message.message">{{message.text||message.answer||message.message}}</p><small v-if="message.ticket_no">已转人工，工单：{{message.ticket_no}} · 会话状态：{{message.customer_service_session_status||'waiting_human'}}</small><div v-if="message.overall_status==='needs_clarification'||message.clarification" class="agent-clarification" data-testid="agent-clarification"><strong>需要补充信息</strong><p>{{message.clarification||'请根据提示补充查询条件后重试。'}}</p></div><AnalysisResultCard v-for="(item,analysisIndex) in message.analysis_results||[]" :key="analysisIndex" :data="item.data"/><AgentTracePanel v-for="(task,taskIndex) in message.results||[]" :key="`trace-${taskIndex}`" :trace="task.data?.model_tool_trace"/><details v-if="message.citations?.length"><summary>查看参考依据（{{message.citations.length}}）</summary><div v-for="citation in message.citations" :key="citation.chunk_id">{{citation.content}}</div></details><div v-if="displayRecommendation(message)" class="recommendation-card" data-testid="agent-recommendations"><div class="recommendation-head"><strong>适当性产品推荐</strong><small>基于当前客户风险与资产信息</small></div><p v-if="displayRecommendation(message).warnings?.length" class="recommendation-warning">{{displayRecommendation(message).warnings.map((item:any)=>item.message||item).join('；')}}</p><p v-if="displayRecommendation(message).preference_note" class="recommendation-preference">{{displayRecommendation(message).preference_note}}</p><article v-for="product in displayRecommendation(message).matches||[]" :key="product.product_id" class="recommendation-item"><div><strong>{{product.product_name}}</strong><span>{{product.product_risk_level}} · 起购 ¥{{money(product.minimum_amount)}}</span><small>{{product.recommendation_reason||product.reasons?.[0]||'已通过适当性匹配'}}</small></div><button data-testid="agent-recommendation-buy" @click="query=`我要申购“${product.product_name}”${(message.recommended_purchase?.amount_text||'').match(/[0-9]+(?:\.[0-9]+)?(?:万|元)/)?.[0]||product.minimum_amount+'元'}`">准备申购</button></article><p v-if="!displayRecommendation(message).matches?.length">当前没有通过适当性匹配的产品，您可以继续咨询风险或转人工。</p></div><div v-if="message.trade_draft" class="trade-draft-card" data-testid="agent-trade-draft"><template v-if="message.trade_draft.status==='awaiting_user_confirmation'"><div class="trade-draft-head"><strong>申购草稿</strong><span>预检通过</span></div><p><b>{{message.trade_draft.product_name}}</b> · 申购 ¥{{money(message.trade_draft.amount)}}</p><ul><li v-for="reason in message.trade_draft.suitability_reasons" :key="reason">{{reason}}</li></ul><ul v-if="message.trade_draft.warnings?.length" class="trade-warnings"><li v-for="warning in message.trade_draft.warnings" :key="warning">{{warning}}</li></ul><small>草稿有效至 {{new Date(message.trade_draft.expires_at).toLocaleString('zh-CN')}}</small><label class="trade-ack"><input data-testid="agent-trade-ack" v-model="acknowledgedDrafts[message.trade_draft.draft_id]" type="checkbox"/>我已核对产品、金额、风险提示和适当性结果。</label><button data-testid="agent-trade-confirm" class="trade-confirm" :disabled="!acknowledgedDrafts[message.trade_draft.draft_id]||confirmingDraftId!==''" @click="confirmTradeDraft(message)">{{confirmingDraftId===message.trade_draft.draft_id?'正在创建订单…':'确认并创建订单'}}</button></template><template v-else><strong>交易草稿需要补充或暂不能提交</strong><p>{{message.trade_draft.clarification}}</p><button v-for="product in message.trade_draft.product_options||[]" :key="product.id" class="trade-option" @click="query=`我要申购“${product.name}”${message.trade_draft.amount||''}元`">{{product.name}} · {{product.risk_level}} · 起购 ¥{{money(product.minimum_amount)}}</button></template></div></article><p v-if="loading" class="service-typing">{{drafting?'正在生成交易草稿…':recommending?'正在生成产品推荐…':'正在处理…'}}</p></div><p v-if="error" class="error">{{error}}</p><div v-if="humanSessionId" class="service-human-actions"><button @click="closeHuman">结束人工服务</button><span>已接入人工客服：您的新消息将直接发送给客服。</span></div><footer><textarea data-testid="agent-bubble-input" v-model="query" @keydown.enter.exact.prevent="send" placeholder="例如：我要申购“现金管理保本计划”1000元"/><button data-testid="agent-bubble-send" :disabled="loading||!query.trim()" @click="send">发送</button></footer></section></Transition><button data-testid="agent-bubble-launcher" class="agent-bubble-launcher" :class="{open}" @click="toggle" aria-label="打开统一智能助手"><span>{{open?'×':'✦'}}</span><i>智能助手</i><b v-if="unread&&!open">{{unread>99?'99+':unread}}</b></button></div></template>

<style scoped>
.trade-draft-card{margin-top:10px;border:1px solid #93c5fd;background:#eff6ff;border-radius:10px;padding:11px;color:#172554}.trade-draft-card p{margin:7px 0}.trade-draft-card ul{margin:7px 0;padding-left:18px;font-size:12px;line-height:1.55}.trade-draft-head{display:flex;justify-content:space-between;gap:8px}.trade-draft-head span{font-size:11px;color:#166534;background:#dcfce7;border-radius:999px;padding:2px 7px}.trade-warnings{color:#9a3412}.trade-ack{display:flex;gap:6px;align-items:flex-start;font-size:12px;line-height:1.45;margin:9px 0}.trade-confirm{width:100%;border:0;border-radius:8px;background:#1d4ed8;color:#fff;padding:8px;cursor:pointer}.trade-confirm:disabled{opacity:.55;cursor:not-allowed}.trade-option{display:block;width:100%;margin-top:7px;text-align:left;border:1px solid #93c5fd;background:#fff;border-radius:7px;padding:7px;color:#1e3a8a;cursor:pointer}
</style>

<style scoped>
.recommendation-card{margin-top:10px;border:1px solid #c4b5fd;background:#faf5ff;border-radius:10px;padding:11px;color:#2e1065}.recommendation-head{display:flex;justify-content:space-between;gap:8px;align-items:baseline}.recommendation-head small,.recommendation-item span,.recommendation-item small{display:block;color:#6b21a8;font-size:11px}.recommendation-warning{font-size:12px;color:#9a3412}.recommendation-preference{font-size:11px;color:#6b21a8;background:#f3e8ff;border-left:3px solid #c084fc;border-radius:4px;padding:5px 8px;margin:6px 0}.recommendation-item{display:flex;justify-content:space-between;gap:8px;align-items:center;border-top:1px solid #e9d5ff;padding:9px 0}.recommendation-item:first-of-type{margin-top:5px}.recommendation-item button{border:0;border-radius:7px;background:#7c3aed;color:#fff;padding:7px 9px;white-space:nowrap;cursor:pointer}.recommendation-item button:hover{background:#6d28d9}
</style>
